import {
  type BuildSteps,
  type Change,
  compareSnapshots,
  compareWithCurrent,
  createSnapshot,
  type geometry,
  type Inventory,
  type Issue,
  type ProjectSnapshot,
  planSteps,
  readSnapshot,
  type TemplateDefinition,
  type VersionReport,
} from '@kerf/core';
import { desc, eq } from 'drizzle-orm';
import { z } from 'zod';
import type { Database } from '../db/client.ts';
import { PROJECT_STATUSES, projects } from '../db/schema.ts';
import { getInventory } from './tools.ts';

// Projects and their stored snapshots (ARCHITECTURE.md, apps/api). Snapshots are generated by
// core and stored; reads parse them back and compare them with the template's current version.
// Regenerating is always explicit: a new snapshot is made only on create, when the parameters or
// structural inputs change, or on request.

export const ProjectStatus = z.enum(PROJECT_STATUSES);

export const NewProject = z.object({
  name: z.string().trim().min(1).max(200),
  templateId: z.string(),
  status: ProjectStatus.default('planned'),
  params: z.unknown(),
  /** Structural inputs have no defaults; an empty object leaves every check "input needed". */
  structuralInputs: z.unknown(),
});
export type NewProject = z.infer<typeof NewProject>;

export const ProjectChanges = z
  .object({
    name: z.string().trim().min(1).max(200),
    status: ProjectStatus,
    params: z.unknown(),
    structuralInputs: z.unknown(),
  })
  .partial()
  .refine((c) => Object.values(c).some((v) => v !== undefined), 'changes nothing');
export type ProjectChanges = z.infer<typeof ProjectChanges>;

export interface ProjectSummary {
  id: string;
  name: string;
  status: z.infer<typeof ProjectStatus>;
  templateId: string;
  templateVersion: number;
  /** True when the template has a newer version than the one the snapshot was made with. */
  templateBehind: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface Project extends ProjectSummary {
  /**
   * Null only when the stored snapshot cannot be read even after upgrading, which tests guard
   * against (decision 0014); `unreadable` says why.
   */
  snapshot: ProjectSnapshot | null;
  unreadable?: { reason: string; message: string };
  version: VersionReport | null;
  /**
   * The plan's drawings (#90, #91), drawn by core from the stored snapshot on each read. Not
   * stored: a view of the numbers the snapshot holds. Null when the snapshot cannot be read.
   */
  drawings: geometry.Drawings | null;
  /**
   * The build steps (#105, #52), with methods chosen from the current tool inventory on each read,
   * and the key of that inventory so a client can tell when they are stale. In the project
   * response so the shop view needs no other request. Null when the snapshot cannot be read.
   */
  steps: BuildSteps | null;
}

/** A snapshot generated from proposed changes and not saved, with what it changes. */
export interface Preview {
  snapshot: ProjectSnapshot;
  /** Paths in the template's plan whose values differ from the stored snapshot's. */
  changes: Change[];
  truncated: boolean;
}

export type Result<T> =
  | { ok: true; value: T }
  | { ok: false; error: 'not-found' | 'unknown-template' | 'unreadable-snapshot' }
  | { ok: false; error: 'invalid-project'; issues: Issue[] };

type Row = typeof projects.$inferSelect;

/** A snapshot's drawings, from its template; read already, so its outputs parse. */
function drawingsOf(template: TemplateDefinition, snapshot: ProjectSnapshot) {
  return template.drawings(template.outputs.parse(snapshot.outputs));
}

/** A snapshot's build steps for an inventory, from its template; read already, so it parses. */
function stepsOf(template: TemplateDefinition, snapshot: ProjectSnapshot, inventory: Inventory) {
  return planSteps(template, template.outputs.parse(snapshot.outputs), inventory);
}

export function createProjectService(deps: {
  db: Database;
  templates: readonly TemplateDefinition[];
  now: () => Date;
}) {
  const { db, templates, now } = deps;
  const findTemplate = (id: string) => templates.find((t) => t.id === id);

  function summary(row: Row): ProjectSummary {
    const template = findTemplate(row.templateId);
    return {
      id: row.id,
      name: row.name,
      status: ProjectStatus.parse(row.status),
      templateId: row.templateId,
      templateVersion: row.templateVersion,
      templateBehind: template !== undefined && row.templateVersion < template.version,
      createdAt: row.createdAt.toISOString(),
      updatedAt: row.updatedAt.toISOString(),
    };
  }

  /** The stored snapshot, upgraded to the current shape if it was stored in an older one. */
  const read = (row: Row) => readSnapshot(templates, row.snapshot);

  async function view(row: Row): Promise<Result<Project>> {
    const template = findTemplate(row.templateId);
    if (!template) return { ok: false, error: 'unknown-template' };
    const result = read(row);
    if (!result.ok) {
      return {
        ok: true,
        value: {
          ...summary(row),
          snapshot: null,
          unreadable: { reason: result.reason, message: result.message },
          version: null,
          drawings: null,
          steps: null,
        },
      };
    }
    return {
      ok: true,
      value: {
        ...summary(row),
        snapshot: result.snapshot,
        version: compareWithCurrent(template, result.snapshot),
        drawings: drawingsOf(template, result.snapshot),
        steps: stepsOf(template, result.snapshot, await getInventory(db)),
      },
    };
  }

  function generate(templateId: string, params: unknown, structuralInputs: unknown) {
    const template = findTemplate(templateId);
    if (!template) return { ok: false, error: 'unknown-template' } as const;
    const result = createSnapshot(template, params, structuralInputs);
    if (!result.ok) return { ok: false, error: 'invalid-project', issues: result.issues } as const;
    return { ok: true, snapshot: result.output } as const;
  }

  const snapshotColumns = (s: ProjectSnapshot) => ({
    templateVersion: s.templateVersion,
    snapshot: s,
  });

  async function load(id: string): Promise<Row | undefined> {
    const [row] = await db.select().from(projects).where(eq(projects.id, id));
    return row;
  }

  return {
    /**
     * Rewrites every snapshot stored in an older shape in the current one (decision 0014). Runs
     * at each release, after the database migrations. Numbers and timestamps are left alone.
     */
    async upgradeStoredSnapshots(): Promise<{ upgraded: number; unreadable: string[] }> {
      const rows = await db.select().from(projects);
      let upgraded = 0;
      const unreadable: string[] = [];
      for (const row of rows) {
        const result = read(row);
        if (!result.ok) unreadable.push(row.id);
        else if (result.upgradedFrom !== undefined) {
          await db
            .update(projects)
            .set({ snapshot: result.snapshot })
            .where(eq(projects.id, row.id));
          upgraded++;
        }
      }
      return { upgraded, unreadable };
    },

    async list(): Promise<ProjectSummary[]> {
      const rows = await db.select().from(projects).orderBy(desc(projects.updatedAt));
      return rows.map(summary);
    },

    async get(id: string): Promise<Result<Project>> {
      const row = await load(id);
      return row ? view(row) : { ok: false, error: 'not-found' };
    },

    async create(input: NewProject): Promise<Result<Project>> {
      const generated = generate(input.templateId, input.params, input.structuralInputs ?? {});
      if (!generated.ok) return generated;
      const at = now();
      const [row] = await db
        .insert(projects)
        .values({
          name: input.name,
          status: input.status,
          templateId: input.templateId,
          ...snapshotColumns(generated.snapshot),
          createdAt: at,
          updatedAt: at,
        })
        .returning();
      if (!row) throw new Error('Insert returned no row');
      return view(row);
    },

    /** Changing parameters or inputs regenerates with the template's current version. */
    async update(id: string, changes: ProjectChanges): Promise<Result<Project>> {
      const row = await load(id);
      if (!row) return { ok: false, error: 'not-found' };
      let regenerated = {};
      if (changes.params !== undefined || changes.structuralInputs !== undefined) {
        const stored = read(row);
        if (!stored.ok) return { ok: false, error: 'unreadable-snapshot' };
        const generated = generate(
          row.templateId,
          changes.params ?? stored.snapshot.params,
          changes.structuralInputs ?? stored.snapshot.structuralInputs,
        );
        if (!generated.ok) return generated;
        regenerated = snapshotColumns(generated.snapshot);
      }
      const [updated] = await db
        .update(projects)
        .set({
          ...(changes.name !== undefined ? { name: changes.name } : {}),
          ...(changes.status !== undefined ? { status: changes.status } : {}),
          ...regenerated,
          updatedAt: now(),
        })
        .where(eq(projects.id, id))
        .returning();
      if (!updated) return { ok: false, error: 'not-found' };
      return view(updated);
    },

    /**
     * What saving these changes would produce, compared with the stored snapshot, without saving
     * anything (#56). Takes the same changes as `update`; a name or status change alone previews
     * the stored parameters and inputs with the current template version.
     */
    async preview(id: string, changes: ProjectChanges): Promise<Result<Preview>> {
      const row = await load(id);
      if (!row) return { ok: false, error: 'not-found' };
      const template = findTemplate(row.templateId);
      if (!template) return { ok: false, error: 'unknown-template' };
      const stored = read(row);
      if (!stored.ok) return { ok: false, error: 'unreadable-snapshot' };
      const generated = generate(
        row.templateId,
        changes.params ?? stored.snapshot.params,
        changes.structuralInputs ?? stored.snapshot.structuralInputs,
      );
      if (!generated.ok) return generated;
      return {
        ok: true,
        value: {
          snapshot: generated.snapshot,
          ...compareSnapshots(template, stored.snapshot, generated.snapshot),
        },
      };
    },

    /** Regenerates from the stored parameters and inputs with the current template version. */
    async regenerate(id: string): Promise<Result<Project>> {
      const row = await load(id);
      if (!row) return { ok: false, error: 'not-found' };
      const stored = read(row);
      if (!stored.ok) return { ok: false, error: 'unreadable-snapshot' };
      const generated = generate(
        row.templateId,
        stored.snapshot.params,
        stored.snapshot.structuralInputs,
      );
      if (!generated.ok) return generated;
      const [updated] = await db
        .update(projects)
        .set({ ...snapshotColumns(generated.snapshot), updatedAt: now() })
        .where(eq(projects.id, id))
        .returning();
      if (!updated) return { ok: false, error: 'not-found' };
      return view(updated);
    },

    /** Permanent: the project's history rows go with it (they cascade). */
    async remove(id: string): Promise<Result<null>> {
      const deleted = await db
        .delete(projects)
        .where(eq(projects.id, id))
        .returning({ id: projects.id });
      return deleted.length > 0 ? { ok: true, value: null } : { ok: false, error: 'not-found' };
    },
  };
}

export type ProjectService = ReturnType<typeof createProjectService>;
